import numpy as np, pandas as pd

def entropy(y):
    p = y.value_counts(normalize=True)
    return float(-(p * np.log2(p)).sum())

def gain(df, attr, target="Play"):
    w = df[attr].value_counts(normalize=True)
    return entropy(df[target]) - sum(w[v] * entropy(df[df[attr] == v][target]) for v in w.index)

rows = """Sunny Hot High Weak No|Sunny Hot High Strong No|Overcast Hot High Weak Yes|Rain Mild High Weak Yes|Rain Cool Normal Weak Yes
|Rain Cool Normal Strong No|Overcast Cool Normal Strong Yes|Sunny Mild High Weak No|Sunny Cool Normal Weak Yes|Rain Mild Normal Weak Yes
|Sunny Mild Normal Strong Yes|Overcast Mild High Strong Yes|Overcast Hot Normal Weak Yes|Rain Mild High Strong No"""
df = pd.DataFrame([r.split() for r in rows.replace("\n", "").split("|")], columns=["Outlook", "Temp", "Humidity", "Wind", "Play"])

print("Entropy(S) =", round(entropy(df.Play), 3))
for a in ["Outlook", "Humidity", "Wind", "Temp"]:
    print(f"Gain(S, {a}) = {gain(df, a):.3f}")
sunny = df[df.Outlook == "Sunny"]
for a in ["Humidity", "Temp", "Wind"]:
    print(f"Gain(S_sunny, {a}) = {gain(sunny, a):.3f}")
